from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines();defs='\n'.join(x for x in src if x.startswith(('const PAPER=','const t=','const icons=','const icon=','const btn=','const heading=','function home(','function press(')))
inner=defs+"\nlet lang=new URLSearchParams(location.search).get('language')||'ko';\n"+'''
const view=innerWidth,width=Math.min(1060,view-224-(view<=1180?56:64));const h=document.createElement('div');h.innerHTML=home();const paper=h.querySelector('.paper');document.getElementById('fixture').style.width=width+'px';document.getElementById('fixture').append(paper);
paper.querySelector('button').id='WelcomePaper-research';paper.querySelector('p').id='WelcomePaper-body';let actions=0;document.addEventListener('click',e=>{if(e.target.closest('[data-action=research]')){press(e.target.closest('button'));actions++;setTimeout(()=>fetch('/evidence/home-welcomepaper-'+(/Windows/.test(navigator.userAgent)?'windows':'mac')+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(inputRead())}),0)}});
paper.addEventListener('pointerdown',e=>{if(!e.target.closest('button'))setTimeout(()=>fetch('/evidence/home-welcomepaper-'+(/Windows/.test(navigator.userAgent)?'windows':'mac')+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...inputRead(),passive:true})}),0)});
function inputRead(){return {requests:actions,english:lang==='en',viewportWidth:view,focused:document.activeElement===paper.querySelector('button')}}
function read(){const h=paper.parentElement.getBoundingClientRect(),r=paper.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},text=x=>({box:box(x),text:x.textContent,color:getComputedStyle(x).color}),c=paper.children[1],button=paper.querySelector('button'),style=getComputedStyle(paper);return{id:`${lang}-${view}`,root:{x:r.x-h.x,y:r.y-h.y,width:r.width,height:r.height},icon:{box:box(paper.firstElementChild),stroke:getComputedStyle(paper.firstElementChild).color,strokeWidth:getComputedStyle(paper.firstElementChild).strokeWidth},content:{box:box(c),label:text(c.querySelector('.small')),title:text(c.querySelector('h2')),body:text(c.querySelector('p'))},button:{box:box(button),text:button.textContent,color:getComputedStyle(button).color,fontSize:getComputedStyle(button).fontSize,enabled:!button.disabled},style:{display:style.display,columns:style.gridTemplateColumns,rows:style.gridTemplateRows,gap:style.gap,marginTop:style.marginTop,paddingTop:style.paddingTop,paddingBottom:style.paddingBottom,borderTopWidth:style.borderTopWidth,borderTopColor:style.borderTopColor},case:{id:`${lang}-${view}`,width,viewportWidth:view,english:lang==='en'}}}
'''
(o/'welcomepaper-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes());(o/'welcomepaper-inner.html').write_text('<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="welcomepaper-original.css"><style>#fixture{position:absolute;left:30px;top:60px}</style><div id="fixture"></div><script>'+inner+'</script>')
outer='''<!doctype html><meta charset="utf-8"><title>WelcomePaper · original isolation</title><button id="welcomepaper-record">Record WelcomePaper</button><button id="WelcomePaper-language">Toggle paper fixture</button><button id="welcomepaper-input-record">Record Paper input</button><select id="welcomepaper-case" aria-label="Paper fixture case"></select><div id="frames"></div><style>iframe{position:absolute;left:0;top:30px;height:600px}iframe:not(:first-child){visibility:hidden}</style><script>for(const language of ['ko','en'])for(const view of [960,1100,1101,1180,1280,1440]){const f=document.createElement('iframe');f.width=view;f.dataset.case=language+'-'+view;f.src='welcomepaper-inner.html?language='+language+'&viewport='+view;document.getElementById('frames').append(f);const option=document.createElement('option');option.value=f.dataset.case;option.textContent=f.dataset.case;document.getElementById('welcomepaper-case').append(option)}document.getElementById('welcomepaper-case').onchange=e=>{for(const f of document.querySelectorAll('iframe'))f.style.visibility=f.dataset.case===e.target.value?'visible':'hidden'};document.getElementById('WelcomePaper-language').onclick=()=>{const select=document.getElementById('welcomepaper-case');select.value=select.value==='ko-960'?'en-1101':'ko-960';select.dispatchEvent(new Event('change'))};document.getElementById('welcomepaper-input-record').onclick=async()=>{const id=document.getElementById('welcomepaper-case').value;const f=[...document.querySelectorAll('iframe')].find(x=>x.dataset.case===id);const state=f.contentWindow.inputRead();await fetch('/evidence/home-welcomepaper-'+(/Windows/.test(navigator.userAgent)?'windows':'mac')+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)})};document.getElementById('welcomepaper-record').onclick=async()=>{const rows=[];for(const f of document.querySelectorAll('iframe')){await f.contentDocument.fonts.ready;rows.push(f.contentWindow.read())}const res=await fetch('/evidence/home-welcomepaper-'+(/Windows/.test(navigator.userAgent)?'windows':'mac')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows,cases:rows.map(x=>x.case)})});if(!res.ok)throw Error('Record failed');document.getElementById('welcomepaper-record').textContent='WelcomePaper recorded'}</script>'''
(o/'welcomepaper.html').write_text(outer);print('12 literal original papers / real iframe media1100/1101')
